create table if not exists users(id serial primary key,name varchar(120) not null,email varchar(255) unique not null,password_hash text,created_at timestamptz default now());
create table if not exists courses(id serial primary key,title varchar(160) not null,description text,language varchar(80),level varchar(40),created_at timestamptz default now());
create table if not exists enrollments(id serial primary key,user_id integer references users(id) on delete cascade,course_id integer references courses(id) on delete cascade,progress integer default 0,created_at timestamptz default now(),unique(user_id,course_id));
create table if not exists tests(id serial primary key,title varchar(200),language varchar(80),duration_minutes integer default 30);create table if not exists questions(id serial primary key,test_id integer references tests(id) on delete cascade,prompt text not null,options jsonb,answer text);create table if not exists test_attempts(id serial primary key,user_id integer references users(id) on delete cascade,test_id integer references tests(id),score integer,completed_at timestamptz default now());
create table if not exists interview_sessions(id serial primary key,user_id integer references users(id) on delete set null,language varchar(80),score integer,feedback text,created_at timestamptz default now());create table if not exists notes(id serial primary key,user_id integer references users(id) on delete cascade,title varchar(200),content text,created_at timestamptz default now());
insert into courses(title,description,language,level) select 'C Programming','Core syntax, arrays, pointers and problem solving','C','Beginner' where not exists(select 1 from courses where title='C Programming');
insert into courses(title,description,language,level) select 'C++','OOP, STL and competitive programming foundations','C++','Intermediate' where not exists(select 1 from courses where title='C++');
insert into courses(title,description,language,level) select 'Java','OOP, collections, exceptions and DSA','Java','Intermediate' where not exists(select 1 from courses where title='Java');
insert into courses(title,description,language,level) select 'Python','Python programming, automation and AI basics','Python','Beginner' where not exists(select 1 from courses where title='Python');
insert into courses(title,description,language,level) select 'SQL','Queries, joins, aggregation and database design','SQL','Beginner' where not exists(select 1 from courses where title='SQL');
